  jsonb_build_object('id', 'leaders', 'name', 'Leaders', 'entries', jsonb_build_array(
    jsonb_build_object('name', 'Himanta Biswa Sarma', 'party_id', 'BJP', 'const_id', 'AS_VS26_37_JALUKBARI', 'role', 'Chief Minister', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('fbd09591-d1a1-555d-89bf-7440769422c7') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'Wazed Ali Choudhury', 'party_id', 'INC', 'const_id', 'AS_VS26_9_BIRSING_JARUA', 'role', 'Leader of the Opposition', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('05d5e0a1-4dc6-5c72-bdae-83fe2b291d5f') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
    jsonb_build_object('name', 'Gaurav Gogoi', 'party_id', 'INC', 'const_id', 'AS_VS26_100_JORHAT', 'role', 'Assam Congress president, candidate', 'person_id', ((SELECT c.person_id FROM candidates c WHERE c.id IN ('53fb6a9d-65cf-538e-a989-a0a57dced9a3') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1))::text),
